from lib import *
S = SS('w9')
steps = [
    step("逐字段解读一个真实收到的 IPv4 头(向 example.com:80 发请求,取回的第一个带数据的响应包):原始头字节 45 00 03 d4 ce aa 40 00 30 06 2e bf 68 14 17 9a c0 a8 09 64。45 = 版本 4 + 头长 5(×4 = 20 字节);00 = TOS(DSCP 0、ECN 0);03 d4 = 总长 980;ce aa = id 52906;40 00 = 标志 DF + 片偏移 0;30 = TTL 48;06 = 协议 TCP;2e bf = 头校验和 0x2ebf,按反码求和验算通过;接着是 4 字节的源地址(公网 104.20.23.154)和 4 字节的目的地址(本机)。载荷 960 字节 = 总长 980 − 头长 20。", t=tl(S(1)), mark=lidx(S(1), '原始头字节', '总长', 'TTL'), done=lidx(S(1), '版本', 'IHL', 'TOS', 'id', '标志', '片偏移', '协议', '校验和  '), b=bars([['版本+IHL', 1, '1 字节'], ['TOS', 1, '1 字节'], ['总长', 2, '2 字节'], ['id', 2, '2 字节'], ['标志+片偏移', 2, '2 字节'], ['TTL', 1, '1 字节'], ['协议', 1, '1 字节'], ['校验和', 2, '2 字节'], ['源+目的地址', 8, '8 字节']], 8, mark=[8], done=[0, 1, 2, 3, 4, 5, 6, 7]), kv=KV([['头', '固定 20 字节(无选项)'], ['总长 980', '头 20 + 载荷 960'], ['TTL 48', '每过一个路由器减 1']], ['总长 980'])),
    step("收到的包校验和是对的,发出去的呢?同一次会话里,本机发出的第一个带数据的包:校验和 0xf0bd,验算同样通过——真实网卡上 IP 头校验和由内核算好填上(在 lo0 上则是 0,见第 1 篇;TCP 校验和可能由网卡卸载,这里没有验证)。TTL:收到的是 48,本机发出的是 64;公网主机的初始 TTL 常见是 64 / 128 / 255,按 64 推算这个包大约经过了 16 个路由器——是估计,不是 traceroute 的实测。id:收到 52906,发出的是 0;标志位两边都是 DF。现代系统对 TCP 包设 DF,id 只在分片重组时才有用。", t=tl(S(2)), mark=lidx(S(2), '发出的包', 'TTL'), done=lidx(S(2), '收到的包(来自公网)', 'id'), b=bars([['收到的包 TTL', 48, '48'], ['本机发出的包 TTL', 64, '64']], 64, mark=[0], done=[1]), kv=KV([['IP 头校验和', '收到 / 发出的都验算通过'], ['TTL', '收到 48,发出 64(初始值 64)'], ['id', '发出 0(设了 DF)']], ['TTL'])),
    step("TOS / DSCP 字段:在套接字上用 IP_TOS 设置,UDP 包发出去时头里的第 2 字节就是这个值。设 0x00 → 抓到 0x00(DSCP 0);设 0x28 → 0x28(DSCP 10,AF11);设 0xb8 → 0xb8(DSCP 46,EF,常用于语音)。高 6 位是 DSCP,低 2 位是 ECN;内核原样带上,但沿途的路由器是否按它排队、是否会改写,取决于网络设备的策略(没有测)。", t=tl(S(3)), mark=lidx(S(3), '设置的 TOS'), done=lidx(S(3), '设置的 TOS'), b=bars([['DSCP 0', 0, '0x00'], ['DSCP 10 (AF11)', 10, '0x28'], ['DSCP 46 (EF)', 46, '0xb8']], 46, mark=[2], done=[0, 1]), kv=KV([['高 6 位', 'DSCP(区分服务)'], ['低 2 位', 'ECN(拥塞通知)'], ['内核', '原样放进头']], ['高 6 位'])),
    step("IHL > 5 的包带 IP 选项。ping -R(记录路由)在这台 macOS 上发出的请求与收到的应答 IP 头都是 20 字节(IHL=5),没有任何选项——这个 ping 没有生效 RR 选项,所以这里没法用它演示 Record Route。下一节在网段的真实流量里找到了带选项的包。", t=tl(S(4)), mark=lidx(S(4), '请求:', '应答:'), done=lidx(S(4), 'ping 输出', '结论'), kv=KV([['ping -R', '发出的包 IHL=5,无选项'], ['IP 选项', '很少用,IHL > 5 才有'], ['下一节', '在真实流量里找带选项的包']], ['ping -R'])),
    step("协议号字段:这个网段 20 秒里抓到的 IPv4 包:协议 6(TCP)1841 个、17(UDP)714 个、2(IGMP)6 个、1(ICMP)4 个。IHL 分布:2559 个包头是 20 字节,6 个是 24 字节——这 6 个都是 IGMP,选项 4 字节 94 04 00 00:类型 0x94 = Router Alert(复制标志 1、类 0、编号 20),告诉沿途路由器“这个包你要看一眼”,IGMP 就靠它。最常见的 TTL:64 共 1238 个(macOS / Linux 的默认起点)、50 共 721 个、255 共 374 个(网络设备)、1 共 62 个(多半是本地组播,TTL=1 不出本网段)。", t=tl(S(5)), mark=lidx(S(5), '那 6 个 24 字节头', '最常见的 TTL'), done=lidx(S(5), '协议号', 'IHL'), b=bars([['TCP (6)', 1841, '1841'], ['UDP (17)', 714, '714'], ['IGMP (2)', 6, '6'], ['ICMP (1)', 4, '4']], 1841, mark=[2], done=[0, 1, 3]), kv=KV([['协议号', '6 TCP / 17 UDP / 1 ICMP / 2 IGMP'], ['IHL=6 的包', '全是 IGMP,带 Router Alert 选项'], ['TTL=1', '本地组播,不出网段']], ['IHL=6 的包'])),
]
A = mkartw('w9', 9, '网络协议,IPv4,IP头,TTL,DSCP,IP选项,tcpdump,真实验证,动画演示',
    '逐字节解读真实收到的 IPv4 头:45 00 03 d4 ce aa 40 00 30 06 2e bf …(版本 4、IHL 5、总长 980、DF、TTL 48、协议 6、校验和验算通过);发出的包 TTL 64、id 0;IP_TOS 设 0x28 / 0xb8 原样出现在头里;20 秒网段流量里 2559 个 20 字节头、6 个 24 字节头(IGMP 的 Router Alert 选项)。',
    'IPv4 头只有 20 字节,每个字节都有用。这篇抓一个真实的包,按字节拆开每个字段并验算校验和,再看 TTL、TOS、协议号和 IP 选项在真实流量里的样子。',
    [('45 00 03 d4', '真实 IPv4 头的前 4 字节:版本 4、头长 20、TOS 0、总长 980'), ('TTL 48 vs 64', '从公网收到的包 TTL 与本机发出的包 TTL'), ('94 04 00 00', 'IGMP 包头里的 Router Alert 选项,网段 20 秒里唯一出现的 IP 选项')],
    [('固定 20 字节', '<p>版本和头长共 1 字节(4 位 + 4 位),TOS 1 字节,总长 2 字节,id 2 字节,标志 + 片偏移 2 字节,TTL 1 字节,协议 1 字节,校验和 2 字节,源与目的地址各 4 字节。</p>'),
     ('校验和与 TTL', '<p>收到和发出的 IP 头校验和都验算通过(在 lo0 上是 0);TTL 每过一个路由器减 1,从收到的 TTL 可以估计经过了多少跳(只是估计)。</p>'),
     ('TOS / DSCP', '<p>高 6 位 DSCP、低 2 位 ECN;IP_TOS 设什么,头里就是什么,至于路由器是否尊重取决于网络策略。</p>'),
     ('IP 选项', '<p>IHL 大于 5 才有选项,极少见;这台机器的 ping -R 没有产生选项。</p>'),
     ('真实流量', '<p>网段里绝大多数包头都是 20 字节;带选项的几乎只有 IGMP 的 Router Alert。协议号 6 / 17 / 1 / 2 分别是 TCP / UDP / ICMP / IGMP。</p>')],
    steps,
    [ENV_W + '。第一、二节在 en0 上抓向 example.com:80 的一次请求,公网地址是 example.com 的 104.20.23.154(本次解析结果);第三节在 lo0 上抓 UDP;第四节对默认网关 ping -R;第五节抓整个网段 20 秒,统计包头字段;TTL 推算跳数是估计',
     '没有验证:IP 选项在路由器上的处理(多数路径会丢弃带选项的包);真实的 Record Route / 时间戳选项(本机 ping 不产生);DSCP 在路由器上的实际处理;ECN 的使用(见 DSCP 与 ECN 一篇);IPv6 头(见 IPv6 一组)'],
    'IPv4 头部')
